<template>
  <el-card class="common-page-card weekend-duty" v-loading="loading">
    <ProjectArrangementLayout enabled :can-write="canEdit&&!saving">
      <template #personnel><div class="duty-roster-return" @dragover.prevent @drop.prevent="returnPeople"><ArrangementPersonnel :key="month" v-model="selectedPeople" monthly default-collapsed :disabled="!canEdit || saving || loading || !plan.ready" :assignment-counts="counts" :directory-loader="getMonthlyShiftDirectory" :availability-loader="availability" /></div></template>
      <div class="duty-tools"><el-button type="primary" :disabled="pending" @click="operationsVisible=true">复制 / 转移 / 互换</el-button><el-button :disabled="pending" @click="fixedVisible=true">固定值班人员</el-button></div><header class="duty-header"><h3>{{month.slice(0,4)}}年{{Number(month.slice(5))}}月值班安排</h3><div><el-button :disabled="pending||monthChangeDisabled" @click="chooseMonth(-1)">上月安排</el-button><el-button :disabled="pending||monthChangeDisabled" @click="chooseMonth(0)">本月安排</el-button><el-button :disabled="pending||monthChangeDisabled" @click="chooseMonth(1)">下月安排</el-button><el-date-picker :model-value="month" type="month" value-format="YYYY-MM" aria-label="值班月份" :clearable="false" :disabled="pending||monthChangeDisabled" @update:model-value="value=>$emit('update:month',value)" /><el-button :disabled="pending" @click="load">刷新值班</el-button></div></header>
      <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button :disabled="saving" @click="flush">重试保存</el-button></el-alert><el-alert v-if="recovery" title="有未保存到服务器的本机值班安排" type="warning" :closable="false"><el-button :disabled="!canEdit" @click="restore">恢复</el-button><el-button @click="discard">放弃</el-button></el-alert>
      <el-alert v-if="!plan.ready && !loading" title="周末值班安排表尚未初始化，暂不能保存。" type="warning" :closable="false" />
      <p class="duty-hint">按本月所有周六、周日安排，参与部门与班次安排相同。人员可在不同日期重复安排，同一天只安排一次；左侧数字为本月已安排次数。停止操作400毫秒后自动保存，点击“同步”才更新工作台；同步后需点击“修改”才能继续编辑。固定值班人员请在配置窗口调整。</p>
      <div class="duty-matrix-scroll"><table class="duty-matrix"><thead><tr><th class="duty-department">参与部门</th><th v-for="date in plan.dates" :key="date">{{dutyDateLabel(date)}}</th></tr></thead><tbody><tr v-for="department in plan.departments" :key="department.code"><th>{{department.label}}</th><td v-for="date in plan.dates" :key="date" :data-duty-cell="`${department.code}:${date}`" @dragover.prevent @drop.stop.prevent="dropPeople($event,department.code,date)"><div v-for="person in cellPeople(department.code,date)" :key="person.user_id" class="duty-person" :draggable="canEdit && !saving && !person.fixed" @dragstart="dragPerson($event,person)"><span>{{person.name}}<el-tag v-if="person.fixed" size="small" type="info">固定</el-tag><small v-if="!person.active">已停用</small></span><el-button v-if="canEdit&&!person.fixed" link type="danger" :disabled="saving" :aria-label="`撤销${person.name}${date}值班`" @click="remove(person)">×</el-button></div><span v-if="!cellPeople(department.code,date).length" class="duty-drop-hint">拖入值班人员</span></td></tr></tbody></table></div>
      <p v-if="plan.updated_at" class="duty-hint">最近调整：{{plan.updated_by_name}} · {{formatBusinessDateTime(plan.updated_at)}}</p>
      <div class="duty-sync-bar"><span>{{saving?'保存中…':dirty?'待自动保存（400毫秒）':plan.updated_at?'已保存':'尚无修改'}}</span><div><el-button link @click="historyVisible=true">修改记录</el-button><el-button :disabled="pending||!plan.published||plan.can_edit" @click="enableEdit">修改</el-button><el-button :type="plan.needs_sync||dirty?'warning':'primary'" :class="{'needs-sync':plan.needs_sync||dirty}" :disabled="saving||!plan.sync_ready||(!plan.needs_sync&&!dirty&&!plan.can_edit)" :loading="syncing" @click="sync">{{!plan.published?'同步（尚未同步）':plan.needs_sync||dirty?'同步（有未同步修改）':plan.can_edit?'同步':'已同步'}}</el-button></div></div>
    </ProjectArrangementLayout>
    <WeekPlanOperationsDialog v-model="operationsVisible" kind="duty" :source-week="shiftWeek(month+'-01')" @saved="load" @busy="$emit('busy',$event)" />
    <FixedWeekendDutyDialog v-model="fixedVisible" @saved="load" />
    <WeeklyShiftHistoryDialog v-model="historyVisible" kind="duty" :week="month" :public="false" :departments="plan.departments" />
  </el-card>
</template>
<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import ArrangementPersonnel from '@/components/common/ArrangementPersonnel.vue'
import ProjectArrangementLayout from '@/views/project/translation/components/ProjectArrangementLayout.vue'
import {getMonthlyShiftDirectory,getWeekendDutyPlan,saveWeekendDutyPlan,syncWeekendDuty,enableWeekendDutyEdit} from '@/api/monthlyShifts'
import {currentShiftMonth,shiftMonth,shiftWeek} from '@/utils/monthlyShift'
import {dutyCounts,dutyDateLabel,applyDutyDrop} from '@/utils/weekendDuty'
import {formatBusinessDateTime} from '@/utils/dateTime'
import WeekPlanOperationsDialog from './WeekPlanOperationsDialog.vue'
import FixedWeekendDutyDialog from './FixedWeekendDutyDialog.vue'
import WeeklyShiftHistoryDialog from './WeeklyShiftHistoryDialog.vue'
const props=defineProps({month:{type:String,required:true},monthChangeDisabled:Boolean}),emit=defineEmits(['update:month','busy'])
const empty=()=>({ready:false,revision:0,assignments:[],dates:[],departments:[]})
const plan=ref(empty()),selectedPeople=ref([]),loading=ref(false),saving=ref(false),syncing=ref(false),dirty=ref(false),error=ref(''),recovery=ref(null)
const operationsVisible=ref(false),fixedVisible=ref(false),historyVisible=ref(false)
const pending=computed(()=>saving.value||syncing.value||dirty.value)
const canEdit=computed(()=>plan.value.can_edit!==false&&plan.value.sync_ready&&!loading.value&&!syncing.value)
const counts=computed(()=>dutyCounts(plan.value.assignments))
const availability=async()=>({ready:true})
let sequence=0,controller,active=true,timer
const key=()=>`xinshi.duty-draft.v1:${localStorage.getItem('user_id')||'anonymous'}:${props.month}`
function discard(){localStorage.removeItem(key());recovery.value=null}
function checkRecovery(){try{const value=JSON.parse(localStorage.getItem(key())||'null');recovery.value=value&&Array.isArray(value.assignments)?value:null}catch{recovery.value=null}}
function restore(){if(!canEdit.value||!recovery.value)return;if(recovery.value.revision!==plan.value.revision){ElMessage.warning('服务器版本已变化，请核对修改记录');return}queue(recovery.value.assignments);recovery.value=null}
function chooseMonth(offset){if(pending.value||props.monthChangeDisabled)return;emit('update:month',shiftMonth(currentShiftMonth(),offset))}
async function load(){if(pending.value)return;controller?.abort();controller=new AbortController();const id=++sequence;loading.value=true;error.value='';plan.value=empty();selectedPeople.value=[];try{const value=await getWeekendDutyPlan(props.month,{signal:controller.signal});if(active&&id===sequence){plan.value=value;checkRecovery()}}catch(e){if(active&&id===sequence&&e.code!=='ERR_CANCELED')error.value=e.detail||'读取周末值班安排失败'}finally{if(active&&id===sequence)loading.value=false}}
const cellPeople=(department,date)=>plan.value.assignments.filter(row=>row.department===department&&row.date===date)
function dragPerson(event,person){if(!canEdit.value||saving.value||person.fixed){event.preventDefault();return}event.dataTransfer.setData('application/x-weekend-duty',JSON.stringify({month:props.month,date:person.date,user_ids:[person.user_id]}));event.dataTransfer.effectAllowed='move'}
let names=new Map()
function dragged(event){try{const moved=event.dataTransfer.getData('application/x-weekend-duty');if(moved){const data=JSON.parse(moved);return data.month===props.month&&Array.isArray(data.user_ids)?data:null}const values=JSON.parse(event.dataTransfer.getData('application/x-project-personnel'));if(!Array.isArray(values))return null;names=new Map(values.map(row=>[row.id,row.name]));return {user_ids:values.map(row=>row.id)}}catch{return null}}
function queue(values){if(!canEdit.value||saving.value)return;plan.value={...plan.value,assignments:values};dirty.value=true;error.value='';try{localStorage.setItem(key(),JSON.stringify({assignments:values,revision:plan.value.revision}))}catch{error.value='本机备份失败，请确认服务器保存成功后再离开'}clearTimeout(timer);timer=setTimeout(()=>void flush(),400)}
async function flush(){clearTimeout(timer);if(!dirty.value)return plan.value;if(saving.value)return null;const month=props.month,backupKey=key();saving.value=true;try{const value=await saveWeekendDutyPlan(month,{revision:plan.value.revision,assignments:plan.value.assignments.map(({user_id,department,date})=>({user_id,department,date}))});if(active&&month===props.month){plan.value=value;dirty.value=false;error.value='';selectedPeople.value=[];discard()}else localStorage.removeItem(backupKey);return value}catch(e){if(active){error.value=e.detail||'自动保存失败，本机备份已保留';ElMessage.error(error.value)}return null}finally{saving.value=false}}
const version=value=>({revision:value.revision,publication_revision:value.publication_revision||0,fixed_revision:value.fixed_revision||0})
async function enableEdit(){if(pending.value)return;try{plan.value=await enableWeekendDutyEdit(props.month,version(plan.value));ElMessage.success('可继续修改；保存后需点击同步')}catch(e){ElMessage.error(e.detail||'开启修改失败')}}
async function sync(){if(saving.value||syncing.value)return;const value=await flush();if(!value)return;syncing.value=true;try{plan.value=await syncWeekendDuty(props.month,version(value));ElMessage.success('本月值班及修改记录已同步到全部人员工作台')}catch(e){ElMessage.error(e.detail||'同步失败，已保存的安排保留')}finally{syncing.value=false}}
function fixedConflict(data,date){return plan.value.assignments.some(row=>row.fixed&&data.user_ids.includes(row.user_id)&&(row.date===date||row.date===data.date))}
function dropPeople(event,department,date){if(!canEdit.value||saving.value)return;const data=dragged(event);if(!data?.user_ids.length)return;if(fixedConflict(data,date)){ElMessage.warning('请通过固定值班人员调整');return}queue(applyDutyDrop(plan.value.assignments,data.user_ids,date,department,data.date).map(row=>({...row,name:row.name||selectedPeople.value.find(person=>person.id===row.user_id)?.name||names.get(row.user_id)||'待保存人员'})))}
function returnPeople(event){if(!canEdit.value||saving.value||!event.dataTransfer.getData('application/x-weekend-duty'))return;const data=dragged(event);if(!data||fixedConflict(data,data.date))return;queue(plan.value.assignments.filter(row=>row.date!==data.date||!data.user_ids.includes(row.user_id)))}
function remove(person){if(!canEdit.value||person.fixed||saving.value)return;queue(plan.value.assignments.filter(row=>row.date!==person.date||row.user_id!==person.user_id))}
watch(pending,value=>emit('busy',value))
watch(()=>props.month,load);onMounted(load);onBeforeUnmount(()=>{active=false;sequence++;controller?.abort();clearTimeout(timer);if(dirty.value&&!saving.value)void flush();emit('busy',false)})
</script>
<style scoped>
.duty-header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px}.duty-header h3{margin:0}.duty-header>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.duty-header :deep(.el-button+.el-button){margin-left:0}.duty-header :deep(.el-date-editor){width:145px}.duty-hint{font-size:12px;line-height:1.7;color:#64748b}.duty-matrix-scroll{overflow:auto;max-height:70vh}.duty-matrix{border-collapse:separate;border-spacing:0;min-width:100%;table-layout:fixed}.duty-matrix th,.duty-matrix td{border-right:1px solid #dbe3ec;border-bottom:1px solid #dbe3ec;padding:12px;vertical-align:top;min-width:165px}.duty-matrix th{background:#f8fafc;position:sticky;top:0;z-index:2;white-space:nowrap}.duty-matrix th:first-child{left:0;z-index:3;min-width:120px;max-width:120px;white-space:normal;border-left:1px solid #dbe3ec}.duty-matrix thead th{border-top:1px solid #dbe3ec}.duty-matrix tbody th{top:auto;z-index:1}.duty-matrix td{height:105px}.duty-person{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:6px 8px;margin-bottom:6px;border:1px solid #bfdbfe;background:#eff6ff;border-radius:6px;cursor:grab;overflow-wrap:anywhere}.duty-person small{display:block;color:#94a3b8}.duty-drop-hint{font-size:12px;color:#94a3b8}.duty-roster-return{min-width:0}
</style>

<style scoped>.duty-roster-return :deep(.arrangement-personnel){font-size:14px;--el-font-size-base:14px;--el-collapse-header-font-size:14px;padding:8px;gap:8px}.duty-roster-return :deep(.arrangement-personnel .el-collapse-item__header),.duty-roster-return :deep(.personnel-heading strong),.duty-roster-return :deep(.el-checkbox__label){font-size:14px}.duty-roster-return :deep(.el-collapse-item__header){padding-inline:8px!important}</style>

<style scoped>.duty-tools{display:flex;justify-content:flex-end;gap:8px;margin-bottom:12px}.duty-sync-bar{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;padding-top:12px;font-size:12px;color:#64748b}.duty-sync-bar>div{display:flex;align-items:center;gap:8px;margin-left:auto}.duty-sync-bar .el-button+.el-button{margin-left:0}.needs-sync{font-weight:600;box-shadow:0 0 0 2px var(--el-color-warning-light-7)}.duty-person{cursor:default}.duty-person[draggable="true"]{cursor:grab}.duty-matrix{font-size:14px}.duty-matrix-scroll{overflow-y:scroll;scrollbar-gutter:stable}.duty-roster-return :deep(.arrangement-personnel){max-height:70vh;overflow-y:scroll;scrollbar-gutter:stable}</style>